    opacity = 0.8,
    float = true,
})

hl.window_rule({
    name = "windowrule-3",
    match = {
        class = "^(org.gnome.Nautilus)$",
    },
    opacity = 0.8,
})

hl.window_rule({
    name = "windowrule-4",
    match = {
        class = "^(gedit|org.gnome.TextEditor|mousepad)$",
    },
