-- LAYER RULES
--layerrule = blur, rofi
--layerrule = ignorezero, rofi
--layerrule = ignorealpha 0.5, rofi
--layerrule = dimaround, rofi
--layerrule = animation popin 10%, rofi
--layerrule = blur, notifications
--layerrule = ignorezero, notifications
hl.layer_rule({
    name = "layerrule-1",
    match = {
        namespace = "waybar",
    },
    blur = true,
    ignore_alpha = 0.5,
})

--layerrule = ignorezero, waybar
hl.layer_rule({
    name = "layerrule-2",
    match = {
        namespace = "tag:notif*",
    },
    ignore_alpha = 0.5,
})

hl.layer_rule({
    name = "layerrule-3",
    match = {
        namespace = "logout_dialog",
    },
    blur = true,
})

-- SWAYNC BLUR & XRAY
hl.layer_rule({
    name = "layerrule-4",
    match = {
        namespace = "swaync-control-center",
    },
    blur = true,
    ignore_alpha = 0,
    xray = 0,
})

hl.layer_rule({
    name = "layerrule-5",
    match = {
        namespace = "swaync-notification-window",
    },
    blur = true,
    ignore_alpha = 0,
    xray = 0,
})

--FLOAT
hl.window_rule({
    name = "windowrule-10",
    match = {
        tag = "viewer*",
    },
    float = true,
})

-- Ignore maximize requests from apps. You'll probably like this.
hl.window_rule({
    name = "windowrule-11",
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

-- Fix some dragging issues with XWayland
hl.window_rule({
    name = "windowrule-12",
    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = false,
    },
    no_focus = true,
})

-- POP UPS AND DIALOGUES
hl.window_rule({
    name = "windowrule-13",
    match = {
        title = "^(Save As|Save a File|Pick Files)$",
    },
    float = true,
    size = "(monitor_w*0.5) (monitor_h*0.6)",
    center = true,
})

hl.window_rule({
    name = "windowrule-14",
    match = {
        initial_title = "(Open Files)",
    },
    float = true,
    size = "(monitor_w*0.7) (monitor_h*0.6)",
})

